class SignalBoardAlarms:
    """Alarm codes for SignalBoard (17 codes, table from firmware alarm.c)."""
    TEMP_SENSOR_COMM_PARTIAL = "05001"  # Temperature sensor partial channel communication fault
    TEMP_SENSOR_READ_PARTIAL = "05002"  # Temperature sensor partial channel reading fault
    TEMP_SENSOR_FAULT = "05003"  # Temperature sensor fault
    HUMIDITY_SENSOR_COMM = "05004"  # Humidity sensor communication fault
    TEMP_CTRL_OVERLIMIT = "09001"  # Heater temperature over-limit
    TEMP_CTRL_NO_HEAT = "09002"  # Heater not raising temperature
    TEMP_CALIB_IMPLAUSIBLE = "09003"  # Temperature calibration output deviates from the raw sensor reading by more than the allowed envelope (+/-20 C), or is NaN/Inf. The reading has been CLAMPED to that envelope, so control and the 120 C cutout keep working on a sane value, but the calibration coefficients in g_temp_params / g_temp_params2 are wrong and must be re-set. Severe: needs a host CLEAR_ALARM
    ADC_DETECT_FAULT = "07001"  # ADC detection fault
    CHIP_DETECT_FAULT = "07002"  # Chip presence detection fault
    SHORT_CIRCUIT_DETECT_FAULT = "07003"  # Short-circuit detection fault. Raised by ANY full-board or subset short scan that finds a shorted channel (M3.6 — previously only the SHORT_CIRCUIT_DETECT debug command raised it, so the identical scan run by the pad interlock or SHORT_DETECT_CH stayed silent). Only a clean FULL-board scan offers the clear; being severe, it needs a host CLEAR_ALARM
    HV_CAP_CAL_FAULT = "01001"  # HV capacitance calibration fault. Raised when boot-time cap calibration falls back to defaults, or when CAP_CALIBRATE_ML produces no valid level (M3.6 — previously defined but never raised by anything)
    HV_CHAN_DETECT_WARN = "01002"  # HV channel detect fault (non-critical)
    HV_CHAN_DETECT_SEV = "01003"  # HV channel detect fault (critical)
    HV_INACCURATE = "01004"  # HV voltage inaccurate
    CAP_FEEDBACK_SATURATED = "01005"  # Capacitance feedback saturated (charge-amp output at the ADC rail). Raised after a calibration when any level reports over_mask != 0, i.e. points discarded for sitting at the ADC ceiling (M3.6 — previously defined but never raised by anything). See CAP_ML_GET for the per-level masks
    HV_VOLTAGE_DEVIATION = "01006"  # HV voltage deviates >20% from setpoint

    CODES = {
        "01001": "HV capacitance calibration fault. Raised when boot-time cap calibration falls back to defaults, or when CAP_CALIBRATE_ML produces no valid level (M3.6 — previously defined but never raised by anything)",
        "01002": "HV channel detect fault (non-critical)",
        "01003": "HV channel detect fault (critical)",
        "01004": "HV voltage inaccurate",
        "01005": "Capacitance feedback saturated (charge-amp output at the ADC rail). Raised after a calibration when any level reports over_mask != 0, i.e. points discarded for sitting at the ADC ceiling (M3.6 — previously defined but never raised by anything). See CAP_ML_GET for the per-level masks",
        "01006": "HV voltage deviates >20% from setpoint",
        "01007": "HV routing gate forced to the safe path while HV is enabled (HV NOT reaching the electrodes)",
        "05001": "Temperature sensor partial channel communication fault",
        "05002": "Temperature sensor partial channel reading fault",
        "05003": "Temperature sensor fault",
        "05004": "Humidity sensor communication fault",
        "07001": "ADC detection fault",
        "07002": "Chip presence detection fault",
        "07003": "Short-circuit detection fault. Raised by ANY full-board or subset short scan that finds a shorted channel (M3.6 — previously only the SHORT_CIRCUIT_DETECT debug command raised it, so the identical scan run by the pad interlock or SHORT_DETECT_CH stayed silent). Only a clean FULL-board scan offers the clear; being severe, it needs a host CLEAR_ALARM",
        "09001": "Heater temperature over-limit",
        "09002": "Heater not raising temperature",
        "09003": "Temperature calibration output deviates from the raw sensor reading by more than the allowed envelope (+/-20 C), or is NaN/Inf. The reading has been CLAMPED to that envelope, so control and the 120 C cutout keep working on a sane value, but the calibration coefficients in g_temp_params / g_temp_params2 are wrong and must be re-set. Severe: needs a host CLEAR_ALARM",
    }

    @staticmethod
    def to_str(code: str) -> str:
        return SignalBoardAlarms.CODES.get(code, f"Unknown alarm: {code}")


class SignalBoardLOGINResponse(NamedTuple):
    status: int  # 0=success
    identity: str  # since 2026-08-27: same 'module;hw_version;sw_version' string as VERSION, appended after status so one round-trip establishes identity; absent on older firmware (legacy 1-byte reply)

class SignalBoardVERSIONResponse(NamedTuple):
    version_string: str  # module;hw_version;sw_version

class SignalBoardSTATUSResponse(NamedTuple):
    cur_temp: float  # Heater CHANNEL 0 only (see temp_onoff). Saturating since 2026-08-31 [M6]: out-of-range readings report 0xFFFF (>= 655.35 °C) or 0 rather than wrapping — the old sensor-outage fail-safe of 999.0 °C used to alias onto a plausible 343.64 °C. 0 also means the model has no tempctrl.
    target_temp: float  # °C
    out_power: int  # %
    rgy_state: int  # 0=off, 1=red, 2=green, 3=yellow
    light_led_bright: int  # %
    flu_led_bright: int  # ‰
    chip_on_pad: int  # bit0 = debounced presence verdict (0=absent, 1=present) — unchanged meaning and unchanged values, so a host reading this field as a plain boolean still works; bit1 = RAW SENS_PAD_L contact (1 = pin LOW = contact), no debounce; bit2 = RAW SENS_PAD_R contact, no debounce. Bits 1-2 added 2026-08-27 (M3.10) to diagnose the "finicky" pad sensor: the debounce collapsed a genuinely absent device and one side dropping out into the same 0, so a marginal sensor was indistinguishable from an empty pad. They are DIAGNOSTIC ONLY and are sampled every idle-hook pass, so they flip freely on a bouncing sensor — never gate anything on them, and note that only bit0 drives the HV interlock. EVT_CHIP_DETECT also fires on bit0 changes only (raw bits still ride in its payload). Persistent disagreement between bit0 and bits 1-2, or a rising `pad_stat` hold count on the console, means the sensor is marginal.
    chip_cap: float  # sum of the ACTIVE electrodes' capacitance. Firmware value is pF x10 since 2026-08-27 (0.1 pF resolution, ceiling 6553.5 pF — a full 120x10 pF board no longer clips); was pF x100 (ceiling 655.35 pF) on earlier firmware incl. the collaborator 1.5.x line
    chip_short_circuit: int  # 0=ok, 1=short
    chip_res: int
    dev_temp: float  # °C
    dev_hum: float  # %RH
    fan_duty: int  # Bitmask of the fans currently commanded ON: bit0 = fan1 (PB11, every board), bit1 = fan2 (PB7, MCU05 only); 0 = all fans off. Changed 2026-08-28 (WP-UISYNC): the field was named for a PWM box-fan loop that was never finished, nothing ever assigned it, and it was therefore hard 0 in every STATUS ever sent — so a host had no way to read the fan state and had to assume the boot default. It now mirrors CMD_FAN_CTRL (0x12A3) and the EF-restored boot state, so a UI can sync a fan control FROM the board. Still on/off only (the fans are GPIO-driven), never a percentage.
    hv_state: int  # bit0=gate electrically routing HV (pin level), bit1=host-commanded enable, bit2=bypass; bit0!=bit1 means the gate was overridden (see alarm 01007). Replaced the unused photon-counter field 2026-08-27.
    hv_vol: float  # V
    hv_freq: int  # Hz
    cap_match: int
    temp_onoff: int  # [E3][M12] Per-channel heater run-state BITMASK: bit0 = channel 0 running, bit1 = channel 1 running, 0 = both off. Was an OR of the two channels (plain 1) until 2026-08-31; because cur_temp/target_temp/out_power above are CHANNEL 0 ONLY, a heater-1-only run showed the host 'heating is on' beside channel 0's idle temperature with no way to tell which heater was meant. Non-zero still means 'some heater is on', so truthiness tests are unaffected; read channel 1's temperatures with TEMP_READ_INFO(channel=1).

