class SignalBoardCAP_ML_GETResponse(NamedTuple):
    raw: bytes  # FIXED offsets, total 70 bytes. [0] valid u8; [1] n_ref u8 (points MEASURED, 1-8); [2] slope_method u8; [3] fbc u8; [4] offset f32 BE; [8] slope f32 BE; [12] points[8]: slot i at 12+6*i = pf u16 BE + adc f32 BE, slots >= n_ref are ZERO-FILLED padding (pf=0), not omitted; [60] n_fit u8 (points that survived into the fit); [61] drop_mask u8 (bit i = point i excluded from the fit - its pf/adc are still reported so the plateau or blow-up is visible from the host); [62] over_mask u8 (bit i = excluded because it was OVER-RANGE for the level - raw range at the ADC ceiling or a super-proportional rise; subset of drop_mask, the remaining drop_mask bits are the pegged/compressed saturation case); [63] hv_lo_mask u8 (bit i = point i measured at the reduced excitation); [64] hv_lo u16 BE (that excitation, V x100; 0 = none used); [66] hv_scale f32 BE (MEASURED response ratio used to put the hv_lo points on the nominal-excitation curve - NOT cal_hv/hv_lo: the excitation amplitude is not proportional to the setpoint, so the firmware measures the ratio with a bridge cap. 1.0 when no reduced pass ran)

class SignalBoardCAN_RECOVERResponse(NamedTuple):
    ok: int  # 1 = the link is usable now (com created + registered + not bus-off); 0 = still dead, read the trailer for which mode
    esr_before: int  # CAN1 ESR before the attempt (bit2 = BOFF)
    msr_before: int
    esr_after: int
    msr_after: int
    bringup_attempts: int  # bring-up/health-monitor loop passes so far
    flags: int  # same bits as CAN_DIAG.flags
    comidx: int  # registered routing slot, 0xFF = NOT registered (routing dead)
    errcode: int  # live CAN status errcode, 0xFF = unreadable
    reserved: int

class SignalBoardCAN_DIAGResponse(NamedTuple):
    raw: bytes  # 9 BE u32 then 4 u8, 40 bytes total: [0] tx_route_fwd, [4] tx_last_ret, [8] rx_irq, [12] rx_recv, [16] rx_route_hit, [20] rx_route_fwd, [24] bringup_attempts (bring-up/health loop passes), [28] recover_calls (CMD_CAN_RECOVER + health-monitor recoveries), [32] create_calls (can_com_creat() invocations - MUST never exceed 1), [36] flags u8: bit0 com object exists, bit1 link sane now, bit2 link was up at least once, bit3 creation in flight, bit4 bring-up thread alive, bit5 registered in a routing slot, [37] comidx u8 (registered slot; 0xFF = not registered = routing dead), [38] errcode u8 (live CAN status errcode, BUSOFF bit included; 0xFF = unreadable / no com), [39] reserved. Reading it: flags bit0=0 means the com was never created (bring-up is still failing - check bringup_attempts climbing and bit4); bit0=1 with bit5=0 means it exists but is unreachable by the router; bit0=1, bit5=1, bit1=0 means it is registered but the cell is bus-off.

