class SignalBoardProxy:
    """SignalBoard typed proxy — auto-generated from commands.yaml."""

    def __init__(self, transport: 'DropletBotUart'):
        self._transport = transport

    def reset(self) -> None:
        """MCU software reset"""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1200, payload)
        self._transport._w(packet)
        return None

    def login(self, year: int, month: int, day: int, hour: int, minute: int, second: int) -> SignalBoardLOGINResponse | None:
        """Handshake login with timestamp"""
        payload = struct.pack('>BBBBBB', year, month, day, hour, minute, second)
        packet = self._transport._make_cmd_packet(0x1201, payload)
        resp = self._transport._wr(packet, 0x1201, timeout_s=2.0)
        if resp is None:
            return None
        if len(resp) < 1:
            return None
        raw = struct.unpack('>B', resp[:1])
        return SignalBoardLOGINResponse(status=raw[0], identity=resp[1:].decode('utf-8', errors='replace').strip('\x00'))

    def version(self) -> SignalBoardVERSIONResponse | None:
        """Get firmware version"""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1202, payload)
        resp = self._transport._wr(packet, 0x1202, timeout_s=2.0)
        if resp is None:
            return None
        return SignalBoardVERSIONResponse(version_string=resp.decode('utf-8'))

    def hw_reset(self) -> None:
        """Hardware reset self-check"""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1203, payload)
        self._transport._w(packet)
        return None

    def status(self) -> SignalBoardSTATUSResponse | None:
        """Query system status — returns 17 x uint16 fields"""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1204, payload)
        resp = self._transport._wr(packet, 0x1204, timeout_s=3.0)
        if resp is None:
            return None
        if len(resp) < 36:
            return None
        raw = struct.unpack('>HHHHHHHHHHHHHHHHHH', resp[:36])
        return SignalBoardSTATUSResponse(cur_temp=raw[0] * 0.01, target_temp=raw[1] * 0.01, out_power=raw[2], rgy_state=raw[3], light_led_bright=raw[4], flu_led_bright=raw[5], chip_on_pad=raw[6], chip_cap=raw[7] * 0.1, chip_short_circuit=raw[8], chip_res=raw[9], dev_temp=raw[10] * 0.01, dev_hum=raw[11] * 0.01, fan_duty=raw[12], hv_state=raw[13], hv_vol=raw[14] * 0.01, hv_freq=raw[15], cap_match=raw[16], temp_onoff=raw[17])

    def temp_set_target(self, *, channel: int = 0, target: float) -> bool:
        """Set heater target temperature"""
        payload = struct.pack('>Bh', channel, int(round(target / 0.01)))
        packet = self._transport._make_cmd_packet(0x1210, payload)
        return self._transport._wr(packet, 0x1210, timeout_s=2.0) is not None

    def temp_start_stop(self, *, channel: int = 0, enable: int) -> bool:
        """Enable/disable heater control"""
        payload = struct.pack('>BB', channel, enable)
        packet = self._transport._make_cmd_packet(0x1211, payload)
        return self._transport._wr(packet, 0x1211, timeout_s=2.0) is not None

    def temp_read_info(self, channel: int = 0) -> SignalBoardTEMP_READ_INFOResponse | None:
        """Read current temperature info"""
        payload = struct.pack('>B', channel)
        for _attempt in range(2):
            packet = self._transport._make_cmd_packet(0x1212, payload)
            resp = self._transport._wr(packet, 0x1212, timeout_s=2.0)
            if resp is None:
                return None
            if len(resp) < 7:
                return None
            raw = struct.unpack('>Bhhh', resp[:7])
            if raw[0] == channel:
                return SignalBoardTEMP_READ_INFOResponse(channel=raw[0], current=raw[1] * 0.01, target=raw[2] * 0.01, output=raw[3] * 0.01)
            # aliased stale reply from an earlier same-cmd request; retry
        return None

    def temp_read_params(self, channel: int = 0) -> SignalBoardTEMP_READ_PARAMSResponse | None:
        """Read PID parameters"""
        payload = struct.pack('>B', channel)
        for _attempt in range(2):
            packet = self._transport._make_cmd_packet(0x1213, payload)
            resp = self._transport._wr(packet, 0x1213, timeout_s=2.0)
            if resp is None:
                return None
            if len(resp) < 9:
                return None
            raw = struct.unpack('>Bhhhh', resp[:9])
            if raw[0] == channel:
                return SignalBoardTEMP_READ_PARAMSResponse(channel=raw[0], kp=raw[1] * 0.01, ki=raw[2] * 0.01, kd=raw[3] * 0.01, period_ms=raw[4])
            # aliased stale reply from an earlier same-cmd request; retry
        return None

    def temp_set_params(self, *, channel: int = 0, kp: float, ki: float, kd: float, period_ms: int) -> bool:
        """Set PID parameters. CHANGED 2026-08-31 [H11]: the gains are stored immediately (TEMP_READ_PARAMS reflects them at once) but the controller is re-initialized by the temperature-control thread itself, so the new tuning takes effect on the next control period (<= 1 s) instead of being applied from under a running control step. Only Kp/Ki/Kd/period are changed now — this command used to silently also swap the Smith-predictor plant model (gain 0.07 -> 0.05) and the integral clamp (50 -> 30), so a board behaved differently before and after its first tuning write."""
        payload = struct.pack('>Bhhhh', channel, int(round(kp / 0.01)), int(round(ki / 0.01)), int(round(kd / 0.01)), period_ms)
        packet = self._transport._make_cmd_packet(0x1214, payload)
        return self._transport._wr(packet, 0x1214, timeout_s=2.0) is not None

    def rgb_light_ctrl(self, color: int) -> bool:
        """Set RGB indicator LED"""
        payload = struct.pack('>B', color)
        packet = self._transport._make_cmd_packet(0x1221, payload)
        return self._transport._wr(packet, 0x1221, timeout_s=2.0) is not None

    def illumination_ctrl(self, brightness: int) -> bool:
        """Set illumination LED brightness. EF-persisted since 2026-08-28 (key 'ill_bright'): the commanded value is restored at the next boot instead of the lamp coming up dark. A board whose key was never written keeps the compiled default (off). Read the current value back from STATUS.light_led_bright. The flash write is DEFERRED ~3 s after the last set and coalesced (these setters get dragged from sliders; one write per drag, not one per step) — so allow ~3 s of quiet before cutting power if you want the value to survive the reboot. CHANGED 2026-08-31: the deferred write is now bounded and reliable — the deadline is capped at 10 s from the first unpersisted change [M3] (a host re-asserting brightness faster than 3 s, or nudging the other lamp, could previously defer BOTH keys for a whole session), the write is flushed synchronously on every reset path [M4] (RESET, FW_PREPARE, POWER_CTRL(1) and the power button — so 'set it, then reboot to check' now works), and a full worker queue at the deadline retries instead of dropping the write [M2]. While a PMT acquisition holds the dark chamber, a set is recorded but NOT driven onto the lamp [M7]: the chamber stays dark for the rest of the read, the acquisition's exit restores the value you last commanded, and STATUS reflects the live (dark) lamp until then."""
        payload = struct.pack('>B', brightness)
        packet = self._transport._make_cmd_packet(0x1222, payload)
        return self._transport._wr(packet, 0x1222, timeout_s=2.0) is not None

    def fluorescence_ctrl(self, brightness: int) -> bool:
        """Set fluorescence LED brightness (1 byte: 0-255, 2 bytes: 0-65535). EF-persisted since 2026-08-28 (key 'flu_bright'): the commanded value is restored at the next boot, REPLACING the old unconditional ~10% (6554) force-on at every boot; a board whose key was never written still comes up at 6554. The flash write is DEFERRED ~3 s after the last set and coalesced, so dragging the host's percent slider costs one write instead of one per step — allow ~3 s of quiet before cutting power if you want the value to survive the reboot. Only the HOST-commanded value is ever persisted: PMT acquisitions force the chamber dark transiently through the same LED, and that is deliberately NOT persisted. Also since 2026-08-28 the 1-byte form is scaled up to the same 16-bit scale internally, so STATUS.flu_led_bright is unambiguously 0-65535 regardless of which request width was used (the PWM duty is unchanged either way). CHANGED 2026-08-31: the deferred write is now bounded and reliable — the deadline is capped at 10 s from the first unpersisted change [M3] (a host re-asserting brightness faster than 3 s, or nudging the other lamp, could previously defer BOTH keys for a whole session), the write is flushed synchronously on every reset path [M4] (RESET, FW_PREPARE, POWER_CTRL(1) and the power button — so 'set it, then reboot to check' now works), and a full worker queue at the deadline retries instead of dropping the write [M2]. While a PMT acquisition holds the dark chamber, a set is recorded but NOT driven onto the lamp [M7]: the chamber stays dark for the rest of the read, the acquisition's exit restores the value you last commanded, and STATUS reflects the live (dark) lamp until then."""
        payload = struct.pack('>H', brightness)
        packet = self._transport._make_cmd_packet(0x1223, payload)
        return self._transport._wr(packet, 0x1223, timeout_s=2.0) is not None

    def electrode_set_volt(self, amplitude: int) -> bool:
        """Set HV electrode voltage"""
        payload = struct.pack('>B', amplitude)
        packet = self._transport._make_cmd_packet(0x1224, payload)
        return self._transport._wr(packet, 0x1224, timeout_s=2.0) is not None

    def electrode_state(self, states: bytes) -> bool:
        """Set electrode channel states (120 channels as 16 bytes)"""
        payload = struct.pack('>16s', states)
        packet = self._transport._make_cmd_packet(0x1225, payload)
        return self._transport._wr(packet, 0x1225, timeout_s=2.0) is not None

    def electrode_set_freq(self, frequency: int) -> bool:
        """Set electrode actuation frequency"""
        payload = struct.pack('>H', frequency)
        packet = self._transport._make_cmd_packet(0x1226, payload)
        return self._transport._wr(packet, 0x1226, timeout_s=2.0) is not None

    def electrode_state_read(self) -> SignalBoardELECTRODE_STATE_READResponse | None:
        """Read back the current electrode channel states (DropBot get_state_of_channels)"""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1220, payload)
        resp = self._transport._wr(packet, 0x1220, timeout_s=2.0)
        if resp is None:
            return None
        return SignalBoardELECTRODE_STATE_READResponse(states=resp[:16])

