    def pmt_stream(self, onoff: int, avg: int, osr: int) -> SignalBoardPMT_STREAMResponse | None:
        """PMT live streaming start/stop (onoff=1/0). Start replies [samples_per_packet u32 LE] immediately and then 128B data packets flow as unsolicited RESP frames on 0x123F ([pkt_idx u16 LE][n u16 LE][n values u16 LE]) until stop, which replies [total_values u32 LE]. avg = boxcar averaging factor: each streamed value is the mean of avg consecutive 1 kHz samples, so value rate = 1000/avg Hz and packet rate ~16.1/avg per second (avg=16 -> ~1 pkt/s, +~sqrt(N) SNR); 0/1 = raw 1 kHz. Same power/gain/dark-chamber handling as acquire; no length limit, no post-run upload. Sending start while already streaming is a LIVE parameter update (avg + osr applied without restart or sample gap; OSR staged onto the sampling thread). MUTUAL EXCLUSION: start while an acquire (0x1227) or debug (0x122C) session is open — including the acquire's upload phase — replies RESP_BUSY immediately (see section header); wait for that session to end and retry. Stop while nothing streams is an idempotent OK. Host: subscribe(0x123F, cb) on the transport."""
        payload = struct.pack('>BBB', onoff, avg, osr)
        packet = self._transport._make_cmd_packet(0x123E, payload)
        resp = self._transport._wr(packet, 0x123E, timeout_s=3.0)
        if resp is None:
            return None
        if len(resp) < 4:
            return None
        raw = struct.unpack('<I', resp[:4])
        return SignalBoardPMT_STREAMResponse(value=raw[0])

    def pmt_acquire_start(self) -> SignalBoardPMT_ACQUIRE_STARTResponse | None:
        """Start PMT ADC sampling. NOTE: the firmware replies only when sampling COMPLETES; a full-buffer run is 10240 samples at 1 kHz (~10.3 s), so the timeout must exceed that. MUTUAL EXCLUSION: replies RESP_BUSY immediately if a stream (0x123E), debug (0x122C) or another acquire session is open (see PMT section header)."""
        payload = b''
        packet = self._transport._make_cmd_packet(0x1227, payload)
        resp = self._transport._wr(packet, 0x1227, timeout_s=25.0)
        if resp is None:
            return None
        if len(resp) < 2:
            return None
        raw = struct.unpack('<H', resp[:2])
        return SignalBoardPMT_ACQUIRE_STARTResponse(packet_count=raw[0])

    def pmt_gain_set(self, gain: int) -> bool:
        """Set PMT gain. May reply RESP_BUSY if the PMT state lock is contended (bounded 500 ms internal wait) — safe to retry."""
        payload = struct.pack('>B', gain)
        packet = self._transport._make_cmd_packet(0x1229, payload)
        return self._transport._wr(packet, 0x1229, timeout_s=2.0) is not None

    def pmt_power(self, enable: int) -> SignalBoardPMT_POWERResponse | None:
        """PMT power control. May reply RESP_BUSY if the PMT state lock is contended (bounded 500 ms internal wait) — safe to retry."""
