class MotorBoardSTATUSResponse(NamedTuple):
    rst: int  # Reset status
    cabin: int  # Chip tray status
    mag: int  # Magnet status
    flu: int  # Fluorescence filter status
    lpush: int  # Left pogo plate status
    rpush: int  # Right pogo plate status
    pmt: int  # PMT status

class MotorBoardCHIP_CABIN_CTRLResponse(NamedTuple):
    status_data: bytes  # Mechanism status, byte[11]=0xFF on error

class MotorBoardCHIP_CABIN_READResponse(NamedTuple):
    status_data: bytes

class MotorBoardMAG_CTRLResponse(NamedTuple):
    status_data: bytes

class MotorBoardMAG_READResponse(NamedTuple):
    status_data: bytes

